const release18Words={sending:['Göndərilir…','Gönderiliyor…','Отправка…','Sending…','جارٍ الإرسال…'],sent:['Fikrin göndərildi. Təşəkkür edirik!','Fikrin gönderildi, teşekkürler!','Идея отправлена. Спасибо!','Your idea was posted. Thank you!','أُرسلت فكرتك، شكرًا لك!'],invalidIdea:['Başlıq ən az 3, mətn ən az 5 simvol olsun və qaydaları qəbul edin.','Başlık en az 3, metin 5 karakter olmalı. Kuralları kabul edin.','Заголовок — от 3, текст — от 5 символов. Примите правила.','Use at least 3 characters for the title and 5 for the text, and accept the rules.','العنوان ٣ أحرف على الأقل والنص ٥، واقبل القواعد.'],rulesSummary:['Təhqir, nifrət, hədə, şəxsi məlumatların ifşası, saxtakarlıq və spam qadağandır.','Hakaret, nefret, tehdit, özel bilgi ifşası, dolandırıcılık ve spam yasaktır.','Оскорбления, ненависть, угрозы, раскрытие личных данных, обман и спам запрещены.','Abuse, hate, threats, exposing private information, fraud and spam are prohibited.','يُحظر الإساءة والكراهية والتهديد وكشف المعلومات الخاصة والاحتيال والرسائل المزعجة.'],acceptRules:['Paylaşım qaydalarını oxudum və qəbul edirəm.','Paylaşım kurallarını okudum ve kabul ediyorum.','Я прочитал(а) и принимаю правила публикации.','I have read and accept the posting rules.','قرأت قواعد النشر وأوافق عليها.'],terms:['İstifadə qaydaları','Kullanım koşulları','Правила использования','Terms of use','شروط الاستخدام'],privacy:['Məxfilik siyasəti','Gizlilik politikası','Политика конфиденциальности','Privacy policy','سياسة الخصوصية'],report:['Şikayət et','Şikayet et','Пожаловаться','Report','إبلاغ'],block:['İstifadəçini blokla','Kullanıcıyı engelle','Заблокировать автора','Block author','حظر الكاتب'],blocked:['Blokladığım istifadəçilər','Engellediğim kullanıcılar','Заблокированные авторы','Blocked authors','الكتّاب المحظورون'],unblock:['Bloku aç','Engeli kaldır','Разблокировать','Unblock','إلغاء الحظر'],reported:['Şikayət adminə göndərildi.','Şikayet yöneticiye gönderildi.','Жалоба отправлена администрации.','Report sent to the administrator.','أُرسل البلاغ للإدارة.'],spam:['Spam və ya saxtakarlıq','Spam veya dolandırıcılık','Спам или мошенничество','Spam or fraud','رسائل مزعجة أو احتيال'],abuse:['Təhqir, nifrət və ya hədə','Hakaret, nefret veya tehdit','Оскорбления, ненависть или угрозы','Abuse, hate or threats','إساءة أو كراهية أو تهديد'],private:['Şəxsi məlumat və ya uyğun olmayan məzmun','Özel bilgi veya uygunsuz içerik','Личные данные или недопустимый контент','Private information or inappropriate content','معلومات خاصة أو محتوى غير لائق'],other:['Digər','Diğer','Другое','Other','أخرى'],reports:['Məzmun şikayətləri','İçerik şikayetleri','Жалобы на контент','Content reports','بلاغات المحتوى'],resolved:['Baxıldı','İncelendi','Рассмотрено','Reviewed','تمت المراجعة'],deleteAccount:['Hesabımı və məlumatlarımı sil','Hesabımı ve verilerimi sil','Удалить аккаунт и данные','Delete my account and data','حذف حسابي وبياناتي'],deleteNote:['Bu əməl geri qaytarılmır. Bulud hesabı, şəxsi ehtiyat nüsxəsi, rəy və oyun qeydləri silinəcək. Google Play abunəliyi ayrıca ləğv edilməlidir. Təsdiq üçün DELETE yazın.','Bu işlem geri alınamaz. Hesap, bulut yedeği, paylaşımlar ve oyun kayıtları silinir. Google Play aboneliğini ayrıca iptal edin. Onay için DELETE yazın.','Действие необратимо: аккаунт, облачная копия, публикации и игровые записи будут удалены. Подписку Google Play отмените отдельно. Введите DELETE.','This cannot be undone. Your account, cloud backup, posts and quiz records will be deleted. Cancel any Google Play subscription separately. Type DELETE to confirm.','لا يمكن التراجع. سيُحذف الحساب والنسخة السحابية والمنشورات وسجل الألعاب. ألغ اشتراك Google Play بصورة منفصلة. اكتب DELETE للتأكيد.'],deleted:['Hesab və bulud məlumatları silindi.','Hesap ve bulut verileri silindi.','Аккаунт и облачные данные удалены.','Account and cloud data deleted.','حُذف الحساب والبيانات السحابية.'],cancelSubscription:['Play abunəliyini idarə et','Play aboneliğini yönet','Управление подпиской Play','Manage Play subscription','إدارة اشتراك Play'],support:['Dəstək','Destek','Поддержка','Support','الدعم']};
function c18(k){return release18Words[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||release18Words[k]?.[0]||k}
let ideaPosting=false,ideaPostError='',ideaLoadError='',ideaReturn=false,deleteReturn=false,ideaDraft={title:'',body:'',request:null},ideaDeleteBusy=false;
let ideaRefreshQueued=false;
function updateIdeaDraft(field,value){if(!['title','body'].includes(field))return;if(ideaDraft[field]!==value){ideaDraft[field]=value;ideaDraft.request=null}}
function captureIdeaDraft(form){const f=new FormData(form);updateIdeaDraft('title',String(f.get('title')||''));updateIdeaDraft('body',String(f.get('body')||''))}
function ideaRequestId(){return globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function communityFeedHTML(){return (ideaLoadError?`<p class="notice error" role="status">${esc(ideaLoadError)}</p>`:'')+(communityData.length?communityData.filter(p=>!p.hidden).map(p=>ideaHTML(p)).join(''):`<p class="card">${communityBusy?v16('preparing'):c17('empty')}</p>`)+(communityData.length>=communityLimit?`<button class="secondarybtn wide" onclick="communityLimit+=30;loadCommunity()">${c17('more')}</button>`:'')}
function paintIdeaState(){const b=document.querySelector('#ideaSubmit');if(b){b.disabled=ideaPosting;b.textContent=ideaPosting?c18('sending'):cloudState.session?c17('send'):c17('signin')}const e=document.querySelector('#ideaError');if(e)e.textContent=ideaPostError;const f=document.querySelector('#communityForm');if(f?.elements)for(const k of ['title','body'])f.elements[k].readOnly=ideaPosting}
loadCommunity=async function(){if(communityBusy){ideaRefreshQueued=true;return;}communityBusy=true;const owner=cloudState.session?.user?.id;try{const rows=await cloudRequest('/rest/v1/rpc/shams_ideas_list',{p_limit:communityLimit,p_admin:route==='cloudadmin'&&cloudState.admin});if(owner!==cloudState.session?.user?.id){communityLoaded=false;ideaRefreshQueued=true;return;}communityData=rows;communityLoaded=true;ideaLoadError=''}catch(e){ideaLoadError=e.message}finally{communityBusy=false;if(route==='community'){const feed=document.querySelector('#communityFeed');if(feed)feed.innerHTML=communityFeedHTML();paintIdeaState()}else if(route==='cloudadmin'&&!document.querySelector('.modal-layer'))render();if(ideaRefreshQueued){ideaRefreshQueued=false;await loadCommunity()}}};
communityPage=function(){if(!communityLoaded&&!communityBusy)setTimeout(loadCommunity,0);return `<div data-localized="true">${head(c17('community'),'')}<p class="notice">${c17('publicNote')}</p>${cloudState.profile?.disabled?`<p class="card error">${cw('denied')}</p>`:`<form id="communityForm" class="card cloud-form" onsubmit="event.preventDefault();postIdea(this)"><label>${c17('title')}<input name="title" required minlength="3" maxlength="120" value="${esc(ideaDraft.title)}" oninput="updateIdeaDraft('title',this.value)"></label><label>${c17('body')}<textarea name="body" required minlength="5" maxlength="2000" rows="4" oninput="updateIdeaDraft('body',this.value)">${esc(ideaDraft.body)}</textarea></label><p class="notice">${c18('rulesSummary')}</p><label class="cloud-consent"><input type="checkbox" name="terms" required><span>${c18('acceptRules')} <button type="button" class="textbtn" onclick="go('legal/terms')">${c18('terms')}</button></span></label><button id="ideaSubmit" class="goldbtn" ${ideaPosting?'disabled':''}>${ideaPosting?c18('sending'):cloudState.session?c17('send'):c17('signin')}</button></form>`}<p id="ideaError" class="notice error" role="alert">${esc(ideaPostError)}</p><div class="module-actions"><button class="textbtn" onclick="loadCommunity()">${c17('refresh')}</button>${cloudState.session?`<button class="textbtn" onclick="showBlockedIdeas()">${c18('blocked')}</button>`:''}</div><div id="communityFeed">${communityFeedHTML()}</div></div>`};
postIdea=async function(form){if(ideaPosting)return;captureIdeaDraft(form);const f=new FormData(form),title=ideaDraft.title.trim(),body=ideaDraft.body.trim();if(title.length<3||title.length>120||body.length<5||body.length>2000||f.get('terms')!=='on'){ideaPostError=c18('invalidIdea');paintIdeaState();return}if(!cloudState.session){ideaReturn=true;go('account');return}if(cloudState.profile?.disabled){ideaPostError=cw('denied');paintIdeaState();return}const owner=cloudState.session.user.id;ideaDraft.request=ideaDraft.request||ideaRequestId();ideaPosting=true;ideaPostError='';paintIdeaState();try{await cloudRequest('/rest/v1/rpc/shams_idea_send',{p_title:title,p_body:body,p_request:ideaDraft.request,p_terms:'2026-11-04'});if(owner===cloudState.session?.user?.id){ideaDraft={title:'',body:'',request:null};form.reset();const current=document.querySelector('#communityForm');if(current?.elements){current.elements.title.value='';current.elements.body.value='';current.elements.terms.checked=false;}communityLoaded=false;toast(c18('sent'))}}catch(e){if(owner===cloudState.session?.user?.id)ideaPostError=e.message}finally{ideaPosting=false;paintIdeaState();if(owner===cloudState.session?.user?.id)await loadCommunity()}};
function ideaSafetyHTML(p){if(!p.author_id||p.author_id===cloudState.session?.user?.id)return '';return `<div class="idea-safety"><button class="textbtn" onclick="reportIdea('${p.id}')">${c18('report')}</button><button class="textbtn" onclick="blockIdeaAuthor('${p.id}')">${c18('block')}</button></div>`}
const idea18Base=ideaHTML;ideaHTML=function(p,admin=false){return idea18Base(p,admin).replace('</article>',(!admin?ideaSafetyHTML(p):'')+'</article>')};
function requireIdeaAccount(){if(cloudState.session)return true;if(document.querySelector('.modal-layer'))closeContentModal();ideaReturn=true;go('account');return false}
function reportIdea(id){if(!requireIdeaAccount())return;showContentModal(modalHeading(c18('report'))+`<form class="cloud-form" onsubmit="event.preventDefault();sendIdeaReport(this,'${id}')"><label>${c18('report')}<select name="reason">${['spam','abuse','private','other'].map(r=>`<option value="${r}">${c18(r)}</option>`).join('')}</select></label><textarea name="note" maxlength="500" rows="3" aria-label="${ux('note')}"></textarea><button class="goldbtn">${c17('send')}</button></form>`)}
async function sendIdeaReport(form,id){try{const f=new FormData(form);await cloudRequest('/rest/v1/rpc/shams_idea_report',{p_id:id,p_reason:f.get('reason'),p_note:String(f.get('note')||'')});closeContentModal();toast(c18('reported'))}catch(e){toast(e.message)}}
async function blockIdeaAuthor(id){if(!requireIdeaAccount())return;try{await cloudRequest('/rest/v1/rpc/shams_idea_block',{p_id:id});await loadCommunity()}catch(e){toast(e.message)}}
async function showBlockedIdeas(){try{const rows=await cloudRequest('/rest/v1/rpc/shams_idea_blocks',{});showContentModal(modalHeading(c18('blocked'))+rows.map(p=>`<div class="row"><strong class="grow">${esc(p.name)}</strong><button class="secondarybtn" onclick="unblockIdeaAuthor('${p.id}')">${c18('unblock')}</button></div>`).join('')+(rows.length?'':cw('empty')))}catch(e){toast(e.message)}}
async function unblockIdeaAuthor(id){try{await cloudRequest('/rest/v1/rpc/shams_idea_unblock',{p_user:id});closeContentModal();await loadCommunity()}catch(e){toast(e.message)}}
let ideaReports=null;
function showPublicUser(id){const p=leaderData?.rows?.find(p=>p.user_id===id);if(!p||id===cloudState.session?.user?.id)return;showContentModal(modalHeading(p.nickname)+`<div class="module-actions"><button class="secondarybtn" onclick="reportPublicUser('${id}')">${c18('report')}</button><button class="secondarybtn" onclick="blockPublicUser('${id}')">${c18('block')}</button></div>`)}
function reportPublicUser(id){if(!requireIdeaAccount())return;showContentModal(modalHeading(c18('report'))+`<form class="cloud-form" onsubmit="event.preventDefault();sendUserReport(this,'${id}')"><select name="reason" aria-label="${c18('report')}">${['spam','abuse','private','other'].map(r=>`<option value="${r}">${c18(r)}</option>`).join('')}</select><textarea name="note" maxlength="500" aria-label="${ux('note')}"></textarea><button class="goldbtn">${c17('send')}</button></form>`)}
async function sendUserReport(form,id){try{const f=new FormData(form);await cloudRequest('/rest/v1/rpc/shams_user_report',{p_user:id,p_reason:f.get('reason'),p_note:String(f.get('note')||'')});closeContentModal();toast(c18('reported'))}catch(e){toast(e.message)}}
async function blockPublicUser(id){if(!requireIdeaAccount())return;try{await cloudRequest('/rest/v1/rpc/shams_user_block',{p_user:id});closeContentModal();await loadLeaders();await loadCommunity()}catch(e){toast(e.message)}}
async function loadIdeaReports(){if(!cloudState.admin)return;try{ideaReports=await cloudRequest('/rest/v1/rpc/shams_idea_reports',{});if(route==='cloudadmin')render()}catch(e){toast(e.message)}}
async function resolveIdeaReport(id){try{await cloudRequest('/rest/v1/rpc/shams_idea_report_resolve',{p_id:id});await loadIdeaReports()}catch(e){toast(e.message)}}
function deleteAccountPage(){return `<div data-localized="true">${head(c18('deleteAccount'),'')}<section class="card"><p>${c18('deleteNote')}</p><a class="secondarybtn wide" href="https://play.google.com/store/account/subscriptions?sku=shams_premium_yearly&package=com.shams.play" target="_blank" rel="noopener">${c18('cancelSubscription')}</a>${cloudState.session?`<form class="cloud-form" onsubmit="event.preventDefault();deleteMyAccount(this)"><label>DELETE<input name="confirm" required pattern="DELETE" autocomplete="off"></label><label><input type="checkbox" name="local" checked>${delete18('clearLocal')}</label><button class="goldbtn" ${ideaDeleteBusy?'disabled':''}>${c18('deleteAccount')}</button><p id="deleteError" class="error" role="alert"></p></form>`:`<button class="goldbtn wide" onclick="deleteReturn=true;go('account')">${cw('signin')}</button>`}</section></div>`}
async function deleteMyAccount(form){if(ideaDeleteBusy||form.elements.confirm.value!=='DELETE')return;ideaDeleteBusy=true;const button=form.querySelector('button');button.disabled=true;try{await cloudRequest('/functions/v1/account-delete',{confirm:'DELETE'});const local=form.elements.local.checked;await cloudLogout();if(local){window.ShamsAndroid?.clearPrivateData?.();for(const k of [...cloudBackupKeys,'nur-surah','shams-quran-progress','shams-qada','basira-onboarding','basira-profile'])localStorage.removeItem(k);for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(k?.startsWith('nur-surah-'))localStorage.removeItem(k)}}toast(c18('deleted'));location.hash='#account';location.reload()}catch(e){document.querySelector('#deleteError').textContent=e.message}finally{ideaDeleteBusy=false;button.disabled=false}}
const deletionWords={clearLocal:['Bu cihazdakı şəxsi qeydləri də sil','Bu cihazdaki kişisel kayıtları da sil','Удалить личные записи с этого устройства','Also remove private records from this device','حذف السجلات الخاصة من هذا الجهاز أيضًا']};function delete18(k){return deletionWords[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||deletionWords[k]?.[0]||k}
function legalPage(){const kind=location.hash.split('/')[1]||'privacy',data=SHAMS_LEGAL[kind]||SHAMS_LEGAL.privacy,l=lang()==='az'?'az':'en';return `<div class="legal-copy" data-localized="true">${head(data.title[l],'')}${data.sections[l].map(s=>`<section class="card"><h2>${esc(s[0])}</h2><p>${esc(s[1])}</p></section>`).join('')}<a href="mailto:mubaristi@gmail.com">SHAMS · mubaristi@gmail.com</a><p><button class="secondarybtn" onclick="go('delete')">${c18('deleteAccount')}</button></p></div>`}
function initializeRelease18(){
 const paint=cloudPaint;cloudPaint=function(){if(['community','leaderboard','delete'].includes(location.hash.slice(1).split('/')[0])&&!document.querySelector('.modal-layer')){render();if(route==='community')paintIdeaState();return}paint()};
 const auth=cloudAuth;cloudAuth=async function(form){await auth(form);if(cloudState.session){if(ideaReturn){ideaReturn=false;go('community')}else if(deleteReturn){deleteReturn=false;go('delete')}}};
 const logout=cloudLogout;cloudLogout=async function(){await logout();ideaDraft={title:'',body:'',request:null};ideaPostError='';ideaReturn=false;deleteReturn=false;ideaReports=null};
 const account=accountPage;accountPage=function(){return account()+`<section class="card legal-links"><button class="textbtn" onclick="go('legal/privacy')">${c18('privacy')}</button><button class="textbtn" onclick="go('legal/terms')">${c18('terms')}</button><a href="mailto:mubaristi@gmail.com">${c18('support')}</a><button class="textbtn" onclick="go('delete')">${c18('deleteAccount')}</button></section>`};
 const admin=cloudAdminPage;cloudAdminPage=function(){let html=admin();if(cloudState.admin){if(ideaReports===null)setTimeout(loadIdeaReports,0);html+=`<details class="card" open><summary>${c18('reports')}</summary><button class="textbtn" onclick="loadIdeaReports()">${c17('refresh')}</button>${(ideaReports||[]).map(r=>`<article class="idea"><strong>${esc(r.title)}</strong><p>${esc(r.body)}</p><p>${esc(r.reason)} · ${esc(r.note)}</p>${r.post_id?`<button class="secondarybtn" onclick="editIdea('${r.post_id}')">${c17('reply')}</button>`:`<button class="secondarybtn" onclick="toggleCloudUser('${r.user_id}',true)">${c18('block')}</button>`}<button class="textbtn" onclick="resolveIdeaReport('${r.id}')">${c18('resolved')}</button></article>`).join('')||cw('empty')}</details>`}return html};
}
